import {ToolRegistry} from './registry.js';

describe('ToolRegistry.execute', () => {
  it('returns a rejection naming location as required and never calls the executor for {}', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const {result} = await registry.execute('get_weather', {});

    expect({executorCalls, result}).toEqual({executorCalls: 0, result: expect.stringMatching(/location.*required|required.*location/)});
  });
});
EOF
